INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3f5434e3-ec6b-44b7-870b-47004ab1632f', 'c1c2c3d4-3030-4000-8000-000000000030', 26, 'Paz', 'Semana 4 — Integrar', '{"pch": "A paz de Cristo n\u00e3o \u00e9 aus\u00eancia de luta\u2026 \u00e9 presen\u00e7a em meio a ela.", "verse": "Jo 14,27", "lectio": "Leia e pergunte: a paz que eu busco \u00e9 do mundo ou de Deus?", "practice": "Identifique uma fonte de agita\u00e7\u00e3o e entregue-a em sil\u00eancio.", "question": "O que rouba sua paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;